/* core.js - shared materials and geometry helpers for Ancient Rome */
window.Rome = window.Rome || {};

(function () {
  const C = {};

  // ---------------- Materials ----------------
  C.mats = {
    travertine: new THREE.MeshLambertMaterial({ color: 0xd9cfae }),
    marble:     new THREE.MeshLambertMaterial({ color: 0xe9e4d4 }),
    stone:      new THREE.MeshLambertMaterial({ color: 0xb9b09a }),
    stoneDark:  new THREE.MeshLambertMaterial({ color: 0x8e8672 }),
    brick:      new THREE.MeshLambertMaterial({ color: 0xb06a44 }),
    brickDark:  new THREE.MeshLambertMaterial({ color: 0x8e4f33 }),
    roof:       new THREE.MeshLambertMaterial({ color: 0xa8552f }),
    wood:       new THREE.MeshLambertMaterial({ color: 0x7a5b3a }),
    darkWood:   new THREE.MeshLambertMaterial({ color: 0x5d4429 }),
    sand:       new THREE.MeshLambertMaterial({ color: 0xd6c48f }),
    road:       new THREE.MeshLambertMaterial({ color: 0xc7bda4 }),
    cobble:     new THREE.MeshLambertMaterial({ color: 0x9a927e }),
    water:      new THREE.MeshLambertMaterial({ color: 0x3a6f8e, transparent: true, opacity: 0.85 }),
    waterBlue:  new THREE.MeshLambertMaterial({ color: 0x4c88a8, transparent: true, opacity: 0.9 }),
    gold:       new THREE.MeshLambertMaterial({ color: 0xd4af37 }),
    green:      new THREE.MeshLambertMaterial({ color: 0x5d8a3c }),
    foliage:    new THREE.MeshLambertMaterial({ color: 0x4d7a2f }),
    foliageDark:new THREE.MeshLambertMaterial({ color: 0x3c6226 }),
    paintRed:   new THREE.MeshLambertMaterial({ color: 0x9e3b2c }),
    paintBlue:  new THREE.MeshLambertMaterial({ color: 0x3f618c }),
    paintCream: new THREE.MeshLambertMaterial({ color: 0xe3d9bd }),
    concrete:   new THREE.MeshLambertMaterial({ color: 0xb8b0a0 }),
    black:      new THREE.MeshLambertMaterial({ color: 0x2a2622 }),
  };

  const M = C.mats;

  // ---------------- Primitive helpers ----------------
  C.box = function (w, h, d, mat, x, y, z) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x || 0, y || 0, z || 0);
    return m;
  };

  // Gabled roof: triangular prism along the Z axis
  C.gableRoof = function (w, d, h, mat) {
    const g = new THREE.CylinderGeometry(1, 1, d, 3, false);
    const m = new THREE.Mesh(g, mat || M.roof);
    m.rotation.x = Math.PI / 2;
    m.rotation.z = Math.PI; // flat side down
    m.scale.set(w / 1.5, 1, h / 1.5);
    return m;
  };

  // Single column (base + shaft + capital)
  C.column = function (r, h, mat) {
    const g = new THREE.Group();
    const base = C.box(r * 2.6, r * 0.9, r * 2.6, mat || M.marble);
    base.position.y = r * 0.45;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.85, r, h, 10), mat || M.marble);
    shaft.position.y = h / 2 + r * 0.9;
    const cap = C.box(r * 2.4, r * 0.8, r * 2.4, mat || M.marble);
    cap.position.y = h + r * 0.9 + r * 0.4;
    g.add(base, shaft, cap);
    return g;
  };

  // Arch frame geometry (rectangle with arched opening cut out), extruded in +Z
  C.archFrameGeometry = function (w, h, openingW, archH, depth) {
    const s = new THREE.Shape();
    s.moveTo(-w / 2, 0); s.lineTo(w / 2, 0);
    s.lineTo(w / 2, h); s.lineTo(-w / 2, h); s.closePath();
    const half = openingW / 2;
    const r = half;
    const hole = new THREE.Path();
    hole.moveTo(-half, 0);
    hole.lineTo(half, 0);
    hole.lineTo(half, archH);
    hole.absarc(0, archH, r, 0, Math.PI, false);
    hole.lineTo(-half, 0);
    s.holes.push(hole);
    const g = new THREE.ExtrudeGeometry(s, { depth: depth || 1, bevelEnabled: false });
    g.translate(0, 0, -depth / 2);
    return g;
  };

  // A triumphal arch gate (single bay, decorated)
  C.triumphalArch = function (scale, mat) {
    scale = scale || 1; mat = mat || M.travertine;
    const g = new THREE.Group();
    const W = 8 * scale, H = 10 * scale, D = 3.5 * scale;
    // front / back arch frames
    const frameG = C.archFrameGeometry(W, H, 4.2 * scale, 3 * scale, D);
    const front = new THREE.Mesh(frameG, mat);
    const back = new THREE.Mesh(frameG, mat);
    g.add(front, back);
    // side walls
    const sideL = C.box(D, H, 1.4 * scale, mat, -W / 2 + 0.7 * scale, H / 2, 0);
    const sideR = C.box(D, H, 1.4 * scale, mat, W / 2 - 0.7 * scale, H / 2, 0);
    g.add(sideL, sideR);
    // attic
    const attic = C.box(W + 0.4 * scale, 1.6 * scale, D + 0.3 * scale, M.stoneDark, 0, H + 0.8 * scale, 0);
    g.add(attic);
    // statue on top
    const stat = C.box(1.2 * scale, 2.2 * scale, 1.2 * scale, M.gold, 0, H + 2.6 * scale, 0);
    g.add(stat);
    return g;
  };

  // A simple classical temple: high podium, front columns, cella, gabled roof
  C.romanTemple = function (opts) {
    opts = opts || {};
    const nFront = opts.cols || 6;           // columns across the front
    const w = opts.width || 14;              // temple width (x)
    const d = opts.depth || 20;              // temple depth (z)
    const colH = opts.colH || 6;
    const podiumH = opts.podiumH || 2.4;
    const mat = opts.mat || M.travertine;
    const g = new THREE.Group();

    // podium + stairs
    const podium = C.box(w + 4, podiumH, d + 4, mat, 0, podiumH / 2, 0);
    g.add(podium);
    for (let i = 0; i < 4; i++) {
      g.add(C.box(w + 4 + i * 1.2, 0.4, 1.2, mat, 0, podiumH - 0.2 - i * 0.4, d / 2 + 2 + 0.6 + i * 1.2));
    }
    // floor of the pronaos
    g.add(C.box(w, 0.3, d * 0.45, M.stone, 0, podiumH + 0.15, d * 0.25));
    // front colonnade (single front entry, deep porch)
    const spacing = w / (nFront - 1);
    for (let i = 0; i < nFront; i++) {
      const col = C.column(0.55, colH, mat);
      col.position.set(-w / 2 + i * spacing, podiumH + 0.3, d / 2 - 1.5);
      g.add(col);
    }
    // engaged side columns
    for (let i = 1; i < nFront - 1; i++) {
      const sideL = C.column(0.45, colH, mat);
      sideL.position.set(-w / 2 - 0.4, podiumH + 0.3, -d / 2 + 2 + i * (d - 5) / (nFront - 2));
      const sideR = C.column(0.45, colH, mat);
      sideR.position.set(w / 2 + 0.4, podiumH + 0.3, -d / 2 + 2 + i * (d - 5) / (nFront - 2));
      g.add(sideL, sideR);
    }
    // architrave + pediment
    g.add(C.box(w + 1.5, 0.9, 1.6, mat, 0, podiumH + colH + 0.6, d / 2 - 1.5));
    // cella
    const cella = C.box(w * 0.8, colH + 0.9, d * 0.55, mat, 0, podiumH + (colH + 0.9) / 2, -d * 0.18);
    g.add(cella);
    // gabled roof over the full length
    const roof = C.gableRoof(w + 2, d + 3, 2.6, mat === M.brick ? M.brick : M.travertine);
    roof.position.y = podiumH + colH + 1.6;
    g.add(roof);
    return g;
  };

  // Tree
  C.tree = function (scale) {
    scale = scale || 1;
    const g = new THREE.Group();
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.25 * scale, 0.35 * scale, 2.4 * scale, 6), M.wood);
    trunk.position.y = 1.2 * scale;
    const crown = new THREE.Mesh(new THREE.SphereGeometry(1.8 * scale, 7, 6), M.foliage);
    crown.position.y = 3.4 * scale;
    const crown2 = new THREE.Mesh(new THREE.SphereGeometry(1.2 * scale, 7, 6), M.foliageDark);
    crown2.position.set(0.6 * scale, 4.2 * scale, 0.3 * scale);
    g.add(trunk, crown, crown2);
    return g;
  };

  // Point placement helpers for oval / stadium rings
  C.ovalPoint = function (a, b, theta) {
    return { x: a * Math.cos(theta), z: b * Math.sin(theta) };
  };
  C.ovalTangent = function (a, b, theta) {
    const dx = -a * Math.sin(theta), dz = b * Math.cos(theta);
    return Math.atan2(dx, dz);
  };

  // Place a ring of boxes around an oval
  C.ovalRing = function (group, a, b, y, count, boxW, boxD, boxH, mat, cx, cz) {
    for (let i = 0; i < count; i++) {
      const t = (i / count) * Math.PI * 2;
      const p = C.ovalPoint(a, b, t);
      const m = C.box(boxW, boxH, boxD, mat, 0, 0, 0);
      m.position.set((cx || 0) + p.x, (y || 0) + boxH / 2, (cz || 0) + p.z);
      m.rotation.y = -C.ovalTangent(a, b, t);
      group.add(m);
    }
  };

  C.groupAt = function (g, x, y, z, rotY) {
    g.position.set(x || 0, y || 0, z || 0);
    if (rotY) g.rotation.y = rotY;
    return g;
  };

  window.Rome.core = C;
})();

/* terrain.js - historically inspired terrain: Seven Hills, Tiber river, Campus Martius lowland */
window.Rome = window.Rome || {};

(function () {
  // World layout (meters): East = +x, North = +z, Forum at origin.
  const HILLS = [
    { x: 70,  z: 40,    r: 78, h: 46, name: 'Palatine Hill' },    // imperial palaces
    { x: -70, z: 40,    r: 66, h: 44, name: 'Capitoline Hill' }, // Temple of Jupiter
    { x: 110, z: 145,   r: 80, h: 50, name: 'Quirinal Hill' },   // Temple of Serapis, Baths of Constantine
    { x: 52,  z: 100,   r: 46, h: 30, name: 'Viminal Hill' },   // residential
    { x: 155, z: 75,    r: 82, h: 40, name: 'Esquiline Hill' },  // Domus Aurea, Baths of Trajan
    { x: 95,  z: -75,   r: 64, h: 44, name: 'Caelian Hill' },    // villas, residences
    { x: 12,  z: -135,  r: 58, h: 40, name: 'Aventine Hill' },   // temples, luxury zone
  ];

  // Flattened monumental areas (mixed smoothly toward level l)
  const FLATS = [
    { x: 0,   z: 5,    r: 85, l: 3.0 },   // Roman Forum valley (drained by Cloaca Maxima)
    { x: 38,  z: -30,  r: 95, l: 3.5 },   // Circus Maximus valley (Palatine-Aventine)
    { x: 100, z: 5,    r: 60, l: 4.0 },   // Colosseum plateau
    { x: -85, z: -10,  r: 95, l: 1.2 },   // Campus Martius lowland (flat, inside Tiber bend)
    { x: 70,  z: 40,   r: 30, l: 44 },    // Palatine top (palace terrace)
    { x: -70, z: 40,   r: 26, l: 42 },    // Capitoline top
  ];

  // Tiber river centerline (curves from north to south through the city)
  function riverX(z) {
    return -150 + 60 * Math.sin(z * 0.0045) + 28 * Math.sin(z * 0.0011);
  }
  const RIVER_HALF = 14;      // water half-width
  const RIVER_BANK = 70;      // valley influence half-width

  function smooth(t) { t = Math.max(0, Math.min(1, t)); return t * t * (3 - 2 * t); }

  function baseHeight(x, z) {
    let h = 1.2 * Math.sin(x * 0.011) * Math.cos(z * 0.009) + 0.6 * Math.sin((x + z) * 0.02);
    // seven hills (plateau-shaped gaussians)
    for (let i = 0; i < HILLS.length; i++) {
      const hl = HILLS[i];
      const d = Math.hypot(x - hl.x, z - hl.z);
      const q = 1 - Math.min(1, (d / hl.r) * (d / hl.r));
      if (q > 0) h += hl.h * Math.pow(q, 1.35);
    }
    // Tiber valley
    const dR = Math.abs(x - riverX(z));
    if (dR < RIVER_BANK) {
      h -= 11 * smooth(1 - dR / RIVER_BANK);
    }
    // monumental flats
    for (let i = 0; i < FLATS.length; i++) {
      const f = FLATS[i];
      const d = Math.hypot(x - f.x, z - f.z);
      const w = smooth(1 - Math.min(1, d / f.r));
      if (w > 0) h = h * (1 - w) + f.l * w;
    }
    // riverbed floor
    if (dR < RIVER_HALF + 6) h = Math.min(h, -6 + 3 * (dR / RIVER_HALF));
    return h;
  }

  function heightAt(x, z) { return baseHeight(x, z); }

  function isWater(x, z) { return Math.abs(x - riverX(z)) < RIVER_HALF; }

  // ---------------- Terrain mesh ----------------
  function buildTerrain(scene, opts) {
    opts = opts || {};
    const SIZE = 1500, SEG = 240;
    const geo = new THREE.PlaneGeometry(SIZE, SIZE, SEG, SEG);
    geo.rotateX(-Math.PI / 2);

    const pos = geo.attributes.position;
    const colors = new Float32Array(pos.count * 3);
    const grass  = new THREE.Color(0x7d9a50);
    const grass2 = new THREE.Color(0x6a8a45);
    const sand   = new THREE.Color(0xc9b27a);
    const rock   = new THREE.Color(0x9a9384);
    const stone  = new THREE.Color(0xb5ac98);
    const bed    = new THREE.Color(0x7a6f55);
    const c = new THREE.Color();

    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      const h = baseHeight(x, z);
      pos.setY(i, h);

      const dR = Math.abs(x - riverX(z));
      if (h < 0.5 && dR < RIVER_HALF + 8) c.copy(bed);
      else if (dR < RIVER_HALF + 16) c.lerpColors(sand, grass, (dR - RIVER_HALF - 8) / 16);
      else if (h > 34) c.lerpColors(rock, grass2, Math.max(0, 1 - (h - 34) / 18));
      else c.lerpColors(grass2, grass, Math.min(1, h / 22));
      // monumental flat areas get a paved tint
      let flatW = 0;
      for (let k = 0; k < FLATS.length; k++) {
        const f = FLATS[k];
        const d = Math.hypot(x - f.x, z - f.z);
        if (f.l < 10) { const w = smooth(1 - Math.min(1, d / f.r)); flatW = Math.max(flatW, w); }
      }
      c.lerp(stone, flatW * 0.65);
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.computeVertexNormals();

    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    const mesh = new THREE.Mesh(geo, mat);
    scene.add(mesh);
    return mesh;
  }

  // ---------------- Tiber water ribbon ----------------
  function buildRiver(scene) {
    const pts = [], uvs = [], idx = [];
    const z0 = -720, z1 = 720, step = 24;
    let i = 0;
    for (let z = z0; z <= z1; z += step) {
      const cx = riverX(z);
      // slight width variation
      const w = RIVER_HALF + 2 + 3 * Math.sin(z * 0.02);
      pts.push(cx - w, 0.35, z);
      pts.push(cx + w, 0.35, z);
      if (z > z0) {
        const a = i - 2, b = i - 2 + 1, cc = i, dd = i + 1;
        idx.push(a, cc, b, b, cc, dd);
      }
      i += 2;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const mesh = new THREE.Mesh(geo, new THREE.MeshLambertMaterial({
      color: 0x3a6f8e, transparent: true, opacity: 0.82,
    }));
    scene.add(mesh);

    // sand banks along the river
    const banks = [];
    for (let z = z0; z <= z1; z += step) {
      const cx = riverX(z);
      banks.push(cx - RIVER_HALF - 6, 0.55, z,  cx + RIVER_HALF + 6, 0.55, z);
    }
    return mesh;
  }

  // ---------------- Labels (hill names as floating text sprites) ----------------
  function makeLabel(text, x, y, z, color) {
    const canvas = document.createElement('canvas');
    canvas.width = 512; canvas.height = 128;
    const ctx = canvas.getContext('2d');
    ctx.font = 'bold 56px Georgia';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = color || 'rgba(255,255,240,0.92)';
    ctx.fillText(text, 256, 64);
    const tex = new THREE.CanvasTexture(canvas);
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, opacity: 0.85, depthTest: true }));
    sp.scale.set(40, 10, 1);
    sp.position.set(x, y, z);
    return sp;
  }

  function buildLabels(scene) {
    const labels = [
      ['TIBER', riverX(0) - 20, 6, -180],
      ['CAMPUS MARTIUS', -90, 20, 100],
    ];
    for (let i = 0; i < HILLS.length; i++) {
      labels.push([HILLS[i].name.toUpperCase(), HILLS[i].x, HILLS[i].h + 14, HILLS[i].z]);
    }
    labels.push(['ROMAN FORUM', 0, 26, 10]);
    for (let i = 0; i < labels.length; i++) {
      const l = labels[i];
      scene.add(makeLabel(l[0], l[1], l[2], l[3]));
    }
  }

  window.Rome.terrain = {
    heightAt: heightAt,
    isWater: isWater,
    riverX: riverX,
    HILLS: HILLS,
    FLATS: FLATS,
    RIVER_HALF: RIVER_HALF,
    buildTerrain: buildTerrain,
    buildRiver: buildRiver,
    buildLabels: buildLabels,
    makeLabel: makeLabel,
  };
})();

/* roads.js - the viae (roads) of ancient Rome, plus bridges over the Tiber */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  // Build a terrain-hugging ribbon road through a list of (x, z) points
  function road(points, width, mat, yOff) {
    const g = new THREE.Group();
    const M = C().mats;
    mat = mat || M.road;
    yOff = yOff === undefined ? 0.25 : yOff;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i], p1 = points[i + 1];
      const dx = p1.x - p0.x, dz = p1.z - p0.z;
      const len = Math.hypot(dx, dz);
      const segs = Math.max(2, Math.floor(len / 6));
      for (let s = 0; s < segs; s++) {
        const t0 = s / segs, t1 = (s + 1) / segs;
        const ax = p0.x + dx * t0, az = p0.z + dz * t0;
        const bx = p0.x + dx * t1, azz = p0.z + dz * t1;
        const h0 = T().heightAt(ax, az) + yOff;
        const h1 = T().heightAt(bx, azz) + yOff;
        const midH = (h0 + h1) / 2;
        const m = C().box(len / segs + 0.4, 0.5, width, mat);
        m.position.set((ax + bx) / 2, midH, (az + azz) / 2);
        m.rotation.y = -Math.atan2(dx, dz);
        g.add(m);
        // central stone line (cursus line) for major roads
        if (width > 8) {
          const line = C().box(len / segs + 0.4, 0.55, 0.6, M.cobble);
          line.position.set(m.position.x, midH, m.position.z);
          line.rotation.y = m.rotation.y;
          g.add(line);
        }
      }
    }
    return g;
  }

  // A stone bridge across the Tiber at z, spanning the full river width
  function bridge(z, width) {
    const g = new THREE.Group();
    const M = C().mats;
    const cx = T().riverX(z);
    const w = T().RIVER_HALF + 12;
    const deckY = 1.6;
    const deck = C().box(4, width * 2 + 10, width || 6, M.stone);
    deck.rotation.y = 0;
    // bridge runs along x here (perpendicular to river flow which is along z)
    const b = C().box(w * 2, 1.2, width || 6, M.stone, 0, deckY, 0);
    // side walls
    g.add(b);
    g.add(C().box(w * 2, 0.8, 0.5, M.stoneDark, 0, deckY + 1.0, (width || 6) / 2 + 0.25));
    g.add(C().box(w * 2, 0.8, 0.5, M.stoneDark, 0, deckY + 1.0, -(width || 6) / 2 - 0.25));
    // piers + arches
    for (let px = -w + 14; px <= w - 14; px += 28) {
      g.add(C().box(4, 8, width || 6, M.stone, px, -1, 0));
      const arch = new THREE.Mesh(
        C().archFrameGeometry(28, 6, 18, 4, 3),
        M.stoneDark
      );
      // keep arches as decorative portal faces
    }
    g.position.set(cx, 0, z);
    return g;
  }

  // Road network following the consular roads of the Aurelian plan
  function buildRoads(scene) {
    const g = new THREE.Group();
    const M = C().mats;

    // Via Flaminia - north, from Porta Flaminia down to the Forum
    g.add(road([{ x: 5, z: 345 }, { x: -5, z: 180 }, { x: -5, z: 55 }], 9));
    // Via Appia - from Forum to Porta Appia (SE)
    g.add(road([{ x: 15, z: 30 }, { x: 140, z: -90 }, { x: 300, z: -240 }], 9));
    // Via Ostiensis - south
    g.add(road([{ x: 5, z: 30 }, { x: 10, z: -160 }, { x: 20, z: -330 }], 9));
    // Via Tiburtina - east / NE, passing north of the Colosseum
    g.add(road([{ x: 25, z: 20 }, { x: 90, z: 40 }, { x: 260, z: 120 }, { x: 330, z: 160 }], 8));
    // Via Salaria - northeast
    g.add(road([{ x: 10, z: 50 }, { x: 120, z: 120 }, { x: 260, z: 260 }], 8));
    // Via Labicana - toward Esquiline
    g.add(road([{ x: 60, z: 30 }, { x: 150, z: 70 }, { x: 250, z: 120 }], 6));
    // Via Triumphalis - across the Palatine summit (Capitoline to Palatine)
    g.add(road([{ x: -40, z: 42 }, { x: 70, z: 40 }, { x: 160, z: 60 }], 5, M.cobble));
    // Via Sacra - the sacred road through the Forum
    g.add(road([{ x: -35, z: -35 }, { x: 0, z: 0 }, { x: 45, z: 35 }], 7, M.cobble, 0.35));

    // Paved plateau for the Roman Forum itself
    const forumPave = C().box(120, 0.6, 120, M.cobble, 0, T().heightAt(0, 5) + 0.15, 5);
    g.add(forumPave);
    // Circus Maximus track floor (the flat arena)
    g.add(C().box(50, 0.5, 150, M.sand, 38, T().heightAt(38, -30) + 0.15, -30));
    // Colosseum surroundings
    g.add(C().box(110, 0.5, 100, M.road, 100, T().heightAt(100, 5) + 0.15, 5));
    // Campus Martius exercise ground
    g.add(C().box(90, 0.4, 160, M.sand, -85, T().heightAt(-85, 0) + 0.1, 0));

    // Bridges over the Tiber
    g.add(bridge(-45, 6));   // Pons Fabricius (toward Forum Boarium)
    g.add(bridge(70, 6));    // Pons Aemilius
    g.add(bridge(-230, 5));  // southern bridge

    scene.add(g);
    return g;
  }

  window.Rome.roads = { build: buildRoads, road: road, bridge: bridge };
})();

