/* circuses.js - chariot-racing circuses: the Circus Maximus and the Circus Flaminius */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  // Circus Maximus: in the valley between the Palatine and Aventine hills
  function circusMaximus(scene) {
    const g = new THREE.Group();
    const M = C().mats;
    const CX = 38, CZ = -30;
    const baseY = T().heightAt(CX, CZ);
    const N = 72;

    // ---- tiered seating (cavea) around the track ----
    const TIERS = 9;
    for (let s = 0; s < TIERS; s++) {
      const a = 26 + s * 2.9, b = 72 + s * 2.9;
      const y = baseY + 1.0 + s * 2.1;
      const mat = (s % 3 === 0) ? M.cobble : (s % 3 === 1 ? M.stone : M.travertine);
      C().ovalRing(g, a, b, y, N, (2 * Math.PI * (a + b)) / N * 1.08, 2.6, 2.0, mat, CX, CZ);
    }
    // outer retaining wall
    const ao = 26 + TIERS * 2.9, bo = 72 + TIERS * 2.9;
    C().ovalRing(g, ao, bo, baseY + 1, N, (2 * Math.PI * (ao + bo)) / N * 1.1, 2.4, 4.5, M.brick, CX, CZ);

    // ---- the spina (central barrier with turning posts - metae) ----
    const spina = C().box(4, 1.2, 100, M.travertine, CX, baseY + 0.6, CZ);
    g.add(spina);
    // metae (cone turning posts) at each end
    for (const s of [-1, 1]) {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(2.5, 6, 10), M.marble);
      cone.position.set(CX, baseY + 3, CZ + s * 52);
      g.add(cone);
      const cone2 = cone.clone();
      cone2.rotation.z = Math.PI / 2 * 0.9;
      cone2.position.set(CX + 3.4, baseY + 3, CZ + s * 52);
      cone2.scale.set(0.8, 0.8, 0.8);
      g.add(cone2);
    }
    // obelisk on one end of the spina
    const ob = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.6, 16, 4), M.stoneDark);
    ob.position.set(CX, baseY + 8.5, CZ - 44);
    g.add(ob);
    const tip = new THREE.Mesh(new THREE.ConeGeometry(1.3, 3, 4), M.stoneDark);
    tip.position.set(CX, baseY + 17.5, CZ - 44);
    g.add(tip);
    // gilded "egg" monument
    const egg = new THREE.Mesh(new THREE.SphereGeometry(2, 10, 10), M.gold);
    egg.position.set(CX, baseY + 2.4, CZ + 44);
    g.add(egg);
    const eggPost = C().box(0.8, 2.4, 0.8, M.marble, CX, baseY + 0.8, CZ + 44);
    g.add(eggPost);

    // entrance (carceres - starting gates) at the north end
    const start = C().triumphalArch(1.4, M.travertine);
    start.position.set(CX - 20, baseY, CZ + 78);
    start.rotation.y = Math.PI / 2;
    g.add(start);

    scene.add(g);
    scene.add(T().makeLabel('CIRCUS MAXIMUS', CX, 32, CZ, 'rgba(255,245,215,0.95)'));
    return g;
  }

  // Circus Flaminius: processional oval along the Tiber bank
  function circusFlaminius(scene) {
    const g = new THREE.Group();
    const M = C().mats;
    const CX = -55, CZ = 20, rot = 0.5;
    const baseY = T().heightAt(CX, CZ);
    const N = 40;
    for (let s = 0; s < 4; s++) {
      const a = 16 + s * 3, b = 40 + s * 3;
      C().ovalRing(g, a, b, baseY + 1 + s * 2, N, (2 * Math.PI * (a + b)) / N * 1.1, 2.4, 1.8,
        s % 2 ? M.stone : M.travertine, CX, CZ);
    }
    g.position.y = 0;
    g.rotation.y = 0; // rings already positioned at CX,CZ
    g.children.forEach(ch => {
      // rotate each ring segment about the circus center
      const px = ch.position.x - CX, pz = ch.position.z - CZ;
      ch.position.set(
        CX + px * Math.cos(rot) - pz * Math.sin(rot),
        ch.position.y,
        CZ + px * Math.sin(rot) + pz * Math.cos(rot)
      );
      ch.rotation.y += -rot;
    });
    scene.add(g);
    scene.add(T().makeLabel('CIRCUS FLAMINIUS', CX, 16, CZ));
    return g;
  }

  function buildCircuses(scene) {
    circusMaximus(scene);
    circusFlaminius(scene);
  }

  window.Rome.circuses = { build: buildCircuses, MAXIMUS: { x: 38, z: -30 } };
})();

/* bathes.js - public bathes (thermae): Caracalla, Diocletian, Constantine, Domus Aurea */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  // A generic thermae complex: frigidarium / tepidarium / caldarium halls with apses
  function thermae(w, d, h, mat) {
    const g = new THREE.Group();
    const M = C().mats;
    // main hall
    g.add(C().box(w, h, d, mat || M.stone, 0, h / 2, 0));
    // central dome (frigidarium)
    const dome = new THREE.Mesh(new THREE.SphereGeometry(w * 0.42, 20, 10, 0, Math.PI * 2, 0, Math.PI / 2), M.travertine);
    dome.scale.y = 0.75;
    dome.position.y = h;
    g.add(dome);
    // side apses (caldarium / tepidarium semicircular halls)
    for (const s of [-1, 1]) {
      const apse = new THREE.Mesh(new THREE.CylinderGeometry(d * 0.42, d * 0.42, h * 0.9, 16, 1, false, 0, Math.PI), M.stone);
      apse.rotation.y = Math.PI / 2;
      apse.rotation.z = 0;
      apse.position.set(s * w / 2, h * 0.9 / 2, 0);
      g.add(apse);
      const adome = new THREE.Mesh(
        new THREE.SphereGeometry(d * 0.42, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2), M.travertine);
      adome.scale.y = 0.7;
      adome.rotation.y = Math.PI / 2;
      adome.position.set(s * w / 2, h * 0.9, 0);
      g.add(adome);
    }
    // colonnaded portico across the front
    for (let i = 0; i < Math.floor(w / 6); i++) {
      const col = C().column(0.5, h * 0.55, M.marble);
      col.position.set(-w / 2 + 3 + i * 6, 0, d / 2 + 2);
      g.add(col);
    }
    g.add(C().box(w, 1, 1.5, M.travertine, 0, h * 0.55 + 0.6, d / 2 + 2));
    // courtyard pool
    g.add(C().box(w * 0.5, 0.8, d * 0.5, M.cobble, 0, 0.4, d / 2 + 8));
    const water = C().box(w * 0.42, 0.5, d * 0.42, M.water, 0, 0.85, d / 2 + 8);
    g.add(water);
    return g;
  }

  function place(scene, g, x, z, label, lblH) {
    const y = T().heightAt(x, z);
    g.position.set(x, y, z);
    scene.add(g);
    if (label) scene.add(T().makeLabel(label, x, lblH || 26, z));
    return g;
  }

  function buildBathes(scene) {
    const M = C().mats;

    // ---- Baths of Caracalla (Esquiline side; four corner towers in history) ----
    let b = thermae(60, 34, 16, M.stone);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const tower = C().box(9, 22, 9, M.brick, sx * 30, 11, sz * 17);
      b.add(tower);
      b.add(C().box(10, 1, 10, M.stoneDark, sx * 30, 22.5, sz * 17));
    }
    place(scene, b, 140, 95, 'BATHS OF CARACALLA', 34);

    // ---- Baths of Diocletian (Quirinal, largest of all) ----
    b = thermae(70, 40, 18, M.stone);
    place(scene, b, 95, 165, 'BATHS OF DIOCLETIAN', 36);

    // ---- Baths of Constantine (Quirinal edge) ----
    b = thermae(40, 24, 12, M.stone);
    b.rotation.y = 0.4;
    place(scene, b, 55, 150, 'BATHS OF CONSTANTINE', 24);

    // ---- Domus Aurea (Nero's Golden House, Esquiline park & palace grounds) ----
    const gold = new THREE.MeshLambertMaterial({ color: 0xcfa954 });
    const d = new THREE.Group();
    d.add(C().box(26, 12, 40, gold, 0, 6, 0));
    // rotunda (the great circular hall with the bronze head of the sun)
    const rot = new THREE.Mesh(new THREE.CylinderGeometry(14, 14, 10, 20), gold);
    rot.position.set(20, 5, 10);
    d.add(rot);
    const rd = new THREE.Mesh(new THREE.SphereGeometry(14, 20, 10, 0, Math.PI * 2, 0, Math.PI / 2), M.travertine);
    rd.scale.y = 0.7;
    rd.position.set(20, 10, 10);
    d.add(rd);
    // park: trees and the artificial lake
    for (let i = 0; i < 14; i++) {
      const tr = C().tree(1.4);
      tr.position.set(-18 + (i % 7) * 8, 0, -22 + Math.floor(i / 7) * 14 + (i % 2) * 4);
      d.add(tr);
    }
    const lake = new THREE.Mesh(new THREE.CircleGeometry(12, 20), M.water);
    lake.rotation.x = -Math.PI / 2;
    lake.position.set(-14, 0.5, 8);
    d.add(lake);
    d.rotation.y = -0.35;
    place(scene, d, 168, 55, 'DOMUS AUREA (GOLDEN HOUSE)', 24);

    // ---- Baths of Nero (Esquiline / Baths of Trajan successor) ----
    b = thermae(36, 22, 11, M.stone);
    b.rotation.y = 0.8;
    place(scene, b, 175, 120, 'BATHS OF TRAJAN', 22);
  }

  window.Rome.bathes = { build: buildBathes };
})();

