/* obelisks.js - Egyptian obelisks raised in Rome: Forum, Campus Martius, Circus spina */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  function obelisk(h, mat) {
    const g = new THREE.Group();
    mat = mat || C().mats.stoneDark;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 1.5, h, 4), mat);
    shaft.position.y = h / 2;
    g.add(shaft);
    const tip = new THREE.Mesh(new THREE.ConeGeometry(1.1, h * 0.22, 4), mat);
    tip.position.y = h + h * 0.11;
    g.add(tip);
    // gilded pyramidion
    const gold = new THREE.Mesh(new THREE.ConeGeometry(0.7, h * 0.12, 4), C().mats.gold);
    gold.position.y = h + h * 0.25;
    g.add(gold);
    // pedestal
    g.add(C().box(4.5, 1.6, 4.5, C().mats.stone, 0, -1.6 + 0.8, 0));
    g.add(C().box(3.8, 0.6, 3.8, C().mats.marble, 0, 0.3, 0));
    return g;
  }

  function buildObelisks(scene) {
    // Obelisk of Augustus (Roman Forum)
    let o = obelisk(20);
    const y1 = T().heightAt(-12, 20);
    o.position.set(-12, y1 + 1.2, 20);
    scene.add(o);
    scene.add(T().makeLabel('OBELISK OF AUGUSTUS', -12, 26, 20));

    // Obelisk of Macuteus (Campus Martius)
    o = obelisk(18);
    const y2 = T().heightAt(-90, -8);
    o.position.set(-90, y2 + 1.2, -8);
    scene.add(o);
    scene.add(T().makeLabel('OBELISK (CAMPUS MARTIUS)', -90, 24, -8));

    // Obelisk of the Circus Maximus spina (the famous "Acacus")
    o = obelisk(15);
    const y3 = T().heightAt(38, -74);
    o.position.set(38, y3 + 1.4, -74);
    scene.add(o);
  }

  window.Rome.obelisks = { build: buildObelisks, obelisk: obelisk };
})();

/* columns.js - monumental columns: Column of Trajan, Column of Marcus Aurelius, etc. */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  // A commemorative column: tall shaft with (carved) bands, capital and statue on top
  function monumentalColumn(h, statueColor) {
    const g = new THREE.Group();
    const M = C().mats;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 2.0, h, 18), M.marble);
    shaft.position.y = h / 2;
    g.add(shaft);
    // spiral relief banding
    for (let i = 0; i < 5; i++) {
      const band = new THREE.Mesh(new THREE.CylinderGeometry(2.05, 2.05, 0.5, 18), M.travertine);
      band.position.y = 2 + i * (h / 5);
      g.add(band);
    }
    g.add(C().box(5, 1, 5, M.travertine, 0, h + 0.5, 0));
    g.add(C().box(6, 1.4, 6, M.stone, 0, h - 1.4, 0));
    // gilded statue on top (Constantine / Marcus Aurelius)
    const stat = C().box(1.6, 3, 1.2, statueColor || M.gold, 0, h + 3.2, 0);
    g.add(stat);
    const base = C().box(4, 2.2, 4, M.stone, 0, 1.1, 0);
    g.add(base);
    return g;
  }

  function buildColumns(scene) {
    // Column of Trajan - Forum of Trajan, east of the Roman Forum
    let c = monumentalColumn(26, C().mats.gold);
    const x1 = 22, z1 = -40;
    c.position.set(x1, T().heightAt(x1, z1), z1);
    scene.add(c);
    scene.add(T().makeLabel('COLUMN OF TRAJAN', x1, 32, z1));

    // Column of Marcus Aurelius - on the opposite corner of the forum
    c = monumentalColumn(22, C().mats.gold);
    const x2 = -24, z2 = -34;
    c.position.set(x2, T().heightAt(x2, z2), z2);
    scene.add(c);
    scene.add(T().makeLabel('COLUMN OF MARCUS AURELIUS', x2, 28, z2));

    // Column of Phocas (St Peter's Square site, near the Vatican bank)
    c = monumentalColumn(14, C().mats.marble);
    const x3 = -60, z3 = -70;
    c.position.set(x3, T().heightAt(x3, z3), z3);
    scene.add(c);
  }

  window.Rome.columns = { build: buildColumns, monumentalColumn: monumentalColumn };
})();

/* arches.js - triumphal arches: Titus, Septimius Severus, Constantine, Claudius */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  function buildArches(scene) {
    const M = C().mats;

    // Arch of Titus - east end of the Via Sacra, celebrates the sacking of Jerusalem (70 CE)
    let a = C().triumphalArch(1.5, M.travertine);
    a.position.set(45, T().heightAt(45, 35), 35);
    a.rotation.y = -Math.PI / 4 - Math.PI / 2;   // faces along the Via Sacra
    scene.add(a);
    scene.add(T().makeLabel('ARCH OF TITUS', 45, 17, 35));

    // Arch of Septimius Severus - west end of the Forum, triple-arched (largest)
    a = C().triumphalArch(2.0, M.travertine);
    a.position.set(-36, T().heightAt(-36, -32), -32);
    a.rotation.y = Math.PI / 4 - Math.PI / 2;
    scene.add(a);
    // flanking side arches
    const sideL = C().triumphalArch(1.0, M.travertine);
    sideL.position.set(-44, T().heightAt(-44, -24), -24);
    sideL.rotation.y = a.rotation.y;
    const sideR = C().triumphalArch(1.0, M.travertine);
    sideR.position.set(-28, T().heightAt(-28, -40), -40);
    sideR.rotation.y = a.rotation.y;
    scene.add(sideL, sideR);
    scene.add(T().makeLabel('ARCH OF SEPTIMIUS SEVERUS', -36, 20, -32));

    // Arch of Constantine - just west of the Colosseum, at the end of the Circus
    a = C().triumphalArch(1.8, M.travertine);
    const xc = 62, zc = 30;
    a.position.set(xc, T().heightAt(xc, zc), zc);
    a.rotation.y = Math.PI / 2;
    scene.add(a);
    scene.add(T().makeLabel('ARCH OF CONSTANTINE', xc, 18, zc));

    // Arch of Claudius (Porta Maggiore) - already merged into the wall; a monument here
    a = C().triumphalArch(1.2, M.stone);
    const xg = 60 + 330 * Math.cos(THREE.MathUtils.degToRad(20));
    const zg = 30 + 330 * Math.sin(THREE.MathUtils.degToRad(20));
    a.position.set(xg, T().heightAt(xg, zg), zg);
    a.rotation.y = -THREE.MathUtils.degToRad(20) - Math.PI / 2;
    scene.add(a);
  }

  window.Rome.arches = { build: buildArches };
})();

/* aqueducts.js - masonry aqueduct lines carrying water to fountains, baths and villas */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  // An aqueduct line: piers + arched galleries + a water channel on top
  // points: array of {x, z}; deckY: constant deck elevation (world)
  function aqueductLine(scene, points, deckY, label) {
    const g = new THREE.Group();
    const M = C().mats;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i], p1 = points[i + 1];
      const dx = p1.x - p0.x, dz = p1.z - p0.z;
      const len = Math.hypot(dx, dz);
      const dir = Math.atan2(dx, dz);
      const span = 12;                    // arch span
      const n = Math.max(1, Math.round(len / span));
      const seg = len / n;
      const py = deckY - 6;               // gallery height above lowest pier
      for (let s = 0; s < n; s++) {
        const t0 = s / n, t1 = (s + 1) / n;
        const cx = p0.x + dx * (t0 + t1) / 2;
        const cz = p0.z + dz * (t0 + t1) / 2;
        const ground = T().heightAt(cx, cz);
        const deck = Math.max(deckY, ground + 2.5);
        const h = deck - ground;
        // two piers
        for (const tt of [t0, t1]) {
          const px = p0.x + dx * tt, pz = p0.z + dz * tt;
          const ph = Math.max(2, T().heightAt(px, pz) - ground) + h - 4;
          g.add(C().box(1.6, h - 3, 1.6, M.stone, px, ground + (h - 3) / 2, pz));
        }
        // arched gallery (openings)
        const gallery = C().box(seg + 0.5, 4.5, 2.2, M.travertine, cx, ground + h - 2.25, cz);
        gallery.rotation.y = -dir;
        g.add(gallery);
        // arches under the gallery
        for (let k = 0; k < 3; k++) {
          const ax = cx - (dx / len) * seg / 3 * (1.5 - k);
          const az = cz - (dz / len) * seg / 3 * (1.5 - k);
          const arch = new THREE.Mesh(C().archFrameGeometry(3.6, 4.4, 2.2, 1.4, 2.0), M.stoneDark);
          arch.position.set(ax, ground + 2.2, az);
          arch.rotation.y = -dir + Math.PI / 2;
          g.add(arch);
        }
        // water channel on the deck
        const channel = C().box(seg + 0.5, 1.4, 1.8, M.marble, cx, deck + 0.7, cz);
        channel.rotation.y = -dir;
        g.add(channel);
        const water = C().box(seg + 0.5, 0.5, 1.0, M.water, cx, deck + 1.3, cz);
        water.rotation.y = -dir;
        g.add(water);
      }
    }
    if (label) {
      const mid = points[Math.floor(points.length / 2)];
      scene.add(T().makeLabel(label, (points[0].x + points[points.length - 1].x) / 2, deckY + 10, (points[0].z + points[points.length - 1].z) / 2));
    }
    scene.add(g);
    return g;
  }

  function buildAqueducts(scene) {
    // Aqua Claudia (32 CE) - arrives from the NE across the Quirinal
    aqueductLine(scene, [
      { x: 350, z: 260 }, { x: 250, z: 215 }, { x: 170, z: 175 }, { x: 110, z: 148 },
    ], 24, 'AQUA CLAUDIA');

    // Aqua Alsietina (49 BCE) - crosses the Tiber to serve the Aventine
    aqueductLine(scene, [
      { x: -235, z: -265 }, { x: -185, z: -268 }, { x: -120, z: -262 }, { x: -70, z: -240 },
    ], 14, 'AQUA ALSIETINA');

    // Aqua Marcia branch toward the Esquiline baths
    aqueductLine(scene, [
      { x: 300, z: 150 }, { x: 240, z: 100 }, { x: 185, z: 82 },
    ], 20, 'AQUA MARCIA');
  }

  window.Rome.aqueducts = { build: buildAqueducts, aqueductLine: aqueductLine };
})();

/* fountains.js - public fountains (lacus / nympheum) fed by the aqueducts */
window.Rome = window.Rome || {};

(function () {
  const T = () => window.Rome.terrain;
  const C = () => window.Rome.core;

  // Tiered fountain: basin, column, upper basin, spout
  function fountain(scale, mat) {
    scale = scale || 1; mat = mat || C().mats.travertine;
    const g = new THREE.Group();
    const M = C().mats;
    // lower basin
    const basin = new THREE.Mesh(new THREE.CylinderGeometry(4 * scale, 4.4 * scale, 1.4 * scale, 16), mat);
    basin.position.y = 0.7 * scale;
    g.add(basin);
    const water1 = C().box(6.6 * scale, 0.6 * scale, 6.6 * scale, M.water, 0, 1.3 * scale, 0);
    g.add(water1);
    // central column
    g.add(C().column(0.6 * scale, 3.2 * scale, mat));
    // upper basin
    const upper = new THREE.Mesh(new THREE.CylinderGeometry(2.2 * scale, 2.4 * scale, 0.9 * scale, 14), mat);
    upper.position.y = 3.6 * scale;
    g.add(upper);
    const water2 = C().box(3.4 * scale, 0.5 * scale, 3.4 * scale, M.water, 0, 4.0 * scale, 0);
    g.add(water2);
    // crowning figure
    const figure = C().box(0.9 * scale, 1.8 * scale, 0.9 * scale, M.marble, 0, 4.9 * scale, 0);
    g.add(figure);
    return g;
  }

  // Large nymphaeum fountain: a fountain set into an arched wall
  function nymphaeum(w) {
    w = w || 16;
    const g = new THREE.Group();
    const M = C().mats;
    g.add(C().box(w, 8, 2.5, M.stone, 0, 4, -3));
    const arch = new THREE.Mesh(C().archFrameGeometry(w * 0.7, 6, w * 0.35, 3, 2.2), M.travertine);
    arch.position.set(0, 1.2, -1.6);
    g.add(arch);
    g.add(C().box(w * 0.6, 0.9, 4, M.cobble, 0, 0.45, 2));
    const water = C().box(w * 0.5, 0.5, 3, M.water, 0, 0.95, 2);
    g.add(water);
    g.add(C().column(0.5, 4, M.marble, -w * 0.4, 2, -2.6));
    g.add(C().column(0.5, 4, M.marble, w * 0.4, 2, -2.6));
    g.add(C().box(w, 0.9, 1.2, M.travertine, 0, 8.4, -3));
    return g;
  }

  function buildFountains(scene) {
    let f = fountain(1.6);
    const p1 = { x: -6, z: -6 };
    f.position.set(p1.x, T().heightAt(p1.x, p1.z), p1.z);
    scene.add(f);
    scene.add(T().makeLabel('PUBLIC FOUNTAIN (FORUM)', p1.x, 10, p1.z));

    // Campus Martius - great fountain
    f = fountain(2.2);
    f.position.set(-85, T().heightAt(-85, 60), 60);
    scene.add(f);
    scene.add(T().makeLabel('FOUNTAIN OF MOESIS', -85, 14, 60));

    // Outside the Baths of Caracalla
    f = fountain(1.4);
    f.position.set(140, T().heightAt(140, 122), 122);
    scene.add(f);

    // Caelian hill quarter
    const n = nymphaeum(18);
    n.position.set(95, T().heightAt(95, -60), -60);
